void kernel_seidel_2d(std::size_t tsteps, std::size_t n, auto A) {
	using namespace noarr;

	#pragma scop
	// Traverse time steps using a 1D noarr structure, to stay within the
	// "all loop nests via traverser" rule, even though time is not a
	// dimension of A itself.
	auto t_struct = scalar<char>() ^ vector<'t'>(tsteps);

	traverser(t_struct).for_each([=](auto /*t_state*/) {
