			.template for_dims<'i'>([=](auto trav_i) {
				// i is fixed in trav_i; iterate j inside
				trav_i.template for_each<'j'>([=](auto state) {
					using noarr::idx;
					using noarr::get_indices;

					auto [i, j] = get_indices<'i', 'j'>(state);

