					auto s_i_jp1   = idx<'i', 'j'>(i,     j + 1);

					auto s_ip1_jm1 = idx<'i', 'j'>(i + 1, j - 1);
					auto s_ip1_j   = idx<'i', 'j'>(i + 1, j);
					auto s_ip1_jp1 = idx<'i', 'j'>(i + 1, j + 1);

